"""Event-sourced aggregate."""
import copy


class InvalidEvent(Exception):
    pass


class Aggregate:
    def __init__(self):
        self.state = {'count': 0, 'total': 0}
        self.version = 0
        self.pending = []
        self._seen_seq = set()

    def handle(self, command):
        seq = self.version + len(self.pending) + 1
        events = [{'name': 'added', 'amount': command.get('amount', 0), 'seq': seq}]
        self.pending.extend(events)
        return events

    def apply(self, event):
        name = event.get('name')
        if name != 'added':
            raise InvalidEvent(name)

        seq = event.get('seq')
        if seq is None:
            raise InvalidEvent('missing seq')
        if seq in self._seen_seq:
            raise InvalidEvent(f'duplicate seq {seq}')

        self.state['count'] += 1
        self.state['total'] += event['amount']
        self.version += 1
        self._seen_seq.add(seq)
        self.pending = [e for e in self.pending if e.get('seq') != seq]

    def rehydrate(self, events):
        for event in events:
            self.apply(event)
        return self

    def snapshot(self):
        return copy.deepcopy(self.state)

